import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getItemById, createBooking, getBookingsForStudent } from '../api/listingService';
import { GoogleMap } from '@react-google-maps/api';
import { useGoogleMaps } from '../context/GoogleMapsContext';
import RoomDetailSkeleton from '../components/listings/RoomDetailSkeleton';
import { Button } from '../components/ui/button';
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from '../components/ui/card';
import { Badge } from '../components/ui/badge';
import { Label } from '../components/ui/label';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from '../components/ui/dialog';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../components/ui/tabs';
import { Separator } from '../components/ui/separator';
import { Star, MapPin, Calendar, IndianRupee, User, MessageSquare, Phone, Clock } from 'lucide-react';
import { toast } from "sonner";
import { useAuth } from '../context/AuthContext';
import { DatePicker } from '../components/ui/date-picker';
import ReviewList from '../components/listings/ReviewList';

// Import Carousel components from shadcn
import {
    Carousel,
    CarouselContent,
    CarouselItem,
    CarouselNext,
    CarouselPrevious,
} from "../components/ui/carousel";

const mapContainerStyle = { width: '100%', height: '300px', borderRadius: '0.5rem' };

const AdvancedMarker = ({ position, map, onMarkerError }) => {
    const markerRef = React.useRef(null);

    React.useEffect(() => {
        if (!map || !window.google || !window.google.maps || !window.google.maps.marker) return;

        try {
            const { AdvancedMarkerElement } = window.google.maps.marker;
            if (!AdvancedMarkerElement) return;

            if (!markerRef.current) {
                markerRef.current = new AdvancedMarkerElement({
                    map,
                    position,
                });
            } else {
                markerRef.current.position = position;
            }
        } catch (error) {
            console.warn('AdvancedMarker initialization error:', error);
            if (onMarkerError) onMarkerError(error);
        }

        return () => {
            try {
                if (markerRef.current) {
                    markerRef.current.map = null;
                    markerRef.current = null;
                }
            } catch (error) {
                console.warn('AdvancedMarker cleanup error:', error);
            }
        };
    }, [map, position, onMarkerError]);

    return null;
};

// Helper component for Star Rating
const StarRating = ({ rating }) => {
    const numRating = Number(rating) || 0;
    const fullStars = Math.floor(numRating);
    const hasHalfStar = numRating % 1 !== 0;
    return (
        <div className="flex items-center gap-0.5">
            {[...Array(5)].map((_, i) => (
                <Star
                    key={i}
                    size={14}
                    className={`${i < fullStars ? "fill-amber-400 text-amber-400" : "text-gray-300"} ${i < numRating && i >= fullStars && hasHalfStar ? "opacity-50 fill-amber-400 text-amber-400" : ""}`}
                />
            ))}
            <span className="ml-0.5 text-xs font-medium text-gray-600">{numRating > 0 ? numRating.toFixed(1) : 'No Rating'}</span>
        </div>
    );
};

// Room-specific details component
const RoomDetails = ({ item, ratingStats }) => {

    return (
        <div className="space-y-3 overflow-hidden">
            {/* Title and Address */}
            <div className="min-w-0">
                <h1 className="text-lg sm:text-xl font-bold text-gray-900 truncate">{item.title}</h1>
                <div className="flex items-start gap-2 mt-1">
                    <MapPin className="h-3 w-3 text-gray-500 flex-shrink-0 mt-0.5" />
                    <p className="text-gray-600 text-xs break-words">{item.address}</p>
                </div>
            </div>

            {/* Price - Full width for visibility */}
            <div className="flex items-center gap-2">
                <IndianRupee className="h-4 w-4 text-green-600 flex-shrink-0" />
                <span className="text-xl font-bold text-gray-900">{item.rent}</span>
                <span className="text-gray-600 text-sm">/ month</span>
            </div>

            {/* Rating and Room Type/Gender - Below Price */}
            <div className="flex items-center justify-between gap-2">
                <div className="flex items-center gap-2">
                    <StarRating rating={ratingStats?.average > 0 ? ratingStats.average : (item.rating || 0)} />
                    {ratingStats?.total > 0 && (
                        <span className="text-xs text-gray-500">({ratingStats.total} reviews)</span>
                    )}
                </div>
                <Badge variant="secondary" className="text-xs whitespace-nowrap">
                    {item.roomType} • {item.gender}
                </Badge>
            </div>



            <Separator />

            {/* Facilities */}
            <div className="space-y-2 overflow-hidden">
                <h3 className="font-semibold text-gray-800 text-sm">Facilities</h3>
                <div className="flex flex-wrap gap-1 overflow-hidden">
                    {item.facilities && item.facilities.length > 0 ? (
                        item.facilities.map((facility, index) => (
                            <Badge key={index} variant="outline" className="text-xs">{facility}</Badge>
                        ))
                    ) : (
                        <p className="text-gray-500 text-sm">No facilities listed</p>
                    )}
                </div>
            </div>

            {/* Description */}
            <div className="space-y-2 overflow-hidden">
                <h3 className="font-semibold text-gray-800 text-sm">Description</h3>
                <p className="text-gray-700 text-sm break-words">{item.description || 'No description available.'}</p>
            </div>
        </div>
    );
};

// Owner Contact Component
const OwnerContact = ({ item }) => {
    const [copied, setCopied] = useState(false);

    const copyToClipboard = (text) => {
        if (!text || text === 'N/A') return;
        navigator.clipboard.writeText(text);
        setCopied(true);
        toast.success('Copied to clipboard!');
        setTimeout(() => setCopied(false), 2000);
    };

    const handleCall = () => {
        if (item.ownerPhone && item.ownerPhone !== 'N/A') {
            window.location.href = `tel:${item.ownerPhone}`;
        }
    };

    const handleWhatsApp = () => {
        if (item.ownerWhatsapp && item.ownerWhatsapp !== 'N/A') {
            const phone = item.ownerWhatsapp.replace(/\D/g, '');
            window.open(`https://wa.me/${phone}`, '_blank');
        }
    };

    return (
        <Card className="border-2 border-gray-200 overflow-hidden">
            <CardHeader>
                <CardTitle className="flex items-center gap-2 text-lg">
                    <User className="h-5 w-5 text-primary" />
                    Owner Information
                </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
                <div className="flex items-center justify-between gap-2">
                    <span className="text-gray-600">Owner Name</span>
                    <span className="font-medium truncate">{item.ownerName || 'N/A'}</span>
                </div>
                <div className="flex items-center justify-between gap-2">
                    <span className="text-gray-600">Phone</span>
                    <div className="flex items-center gap-2 flex-shrink-0">
                        <span className="font-medium truncate">{item.ownerPhone || 'N/A'}</span>
                        {item.ownerPhone && item.ownerPhone !== 'N/A' && (
                            <Button
                                variant="outline"
                                size="sm"
                                onClick={() => copyToClipboard(item.ownerPhone)}
                            >
                                {copied ? 'Copied!' : 'Copy'}
                            </Button>
                        )}
                    </div>
                </div>
                {item.ownerWhatsapp && item.ownerWhatsapp !== 'N/A' && (
                    <div className="flex items-center justify-between gap-2">
                        <span className="text-gray-600">WhatsApp</span>
                        <div className="flex items-center gap-2">
                            <span className="font-medium truncate">{item.ownerWhatsapp}</span>
                        </div>
                    </div>
                )}
                <div className="flex items-center justify-between gap-2">
                    <span className="text-gray-600">Email</span>
                    <div className="flex items-center gap-2 flex-shrink-0">
                        <span className="font-medium truncate">{item.ownerEmail || 'N/A'}</span>
                        {item.ownerEmail && item.ownerEmail !== 'N/A' && (
                            <Button
                                variant="outline"
                                size="sm"
                                onClick={() => copyToClipboard(item.ownerEmail)}
                            >
                                {copied ? 'Copied!' : 'Copy'}
                            </Button>
                        )}
                    </div>
                </div>
                {item.ownerAddress && item.ownerAddress !== 'N/A' && (
                    <div className="flex flex-col">
                        <span className="text-gray-600 mb-1">Address</span>
                        <span className="font-medium text-sm truncate">{item.ownerAddress}</span>
                    </div>
                )}
            </CardContent>
            <CardFooter className="flex flex-col gap-2">
                <Button
                    className="w-full bg-green-600 hover:bg-green-700"
                    onClick={handleCall}
                    disabled={!item.ownerPhone || item.ownerPhone === 'N/A'}
                >
                    <Phone className="h-4 w-4 mr-2" />
                    Call Owner
                </Button>
                <Button
                    variant="outline"
                    className="w-full"
                    onClick={handleWhatsApp}
                    disabled={!item.ownerWhatsapp || item.ownerWhatsapp === 'N/A'}
                >
                    <MessageSquare className="h-4 w-4 mr-2" />
                    WhatsApp Owner
                </Button>
            </CardFooter>
        </Card>
    );
};

// Main Page Component
const RoomDetailPage = () => {
    const { itemId } = useParams();
    const navigate = useNavigate();
    const { user } = useAuth(); // Get user from auth context
    const [item, setItem] = useState(null);
    const [loading, setLoading] = useState(true);
    const [startDate, setStartDate] = useState(null);
    const [bookingNote, setBookingNote] = useState('');
    const [bookingMessage, setBookingMessage] = useState('');
    const [isBookingDialogOpen, setIsBookingDialogOpen] = useState(false);
    const [mapInstance, setMapInstance] = useState(null);
    const [mapError, setMapError] = useState(false);
    const [ratingStats, setRatingStats] = useState({ average: 0, total: 0 });

    const { isLoaded, loadError, isMapsAvailable } = useGoogleMaps();
    const [hasConfirmedBooking, setHasConfirmedBooking] = useState(false);

    useEffect(() => {
        window.scrollTo(0, 0);
    }, []);

    useEffect(() => {
        const checkBookingStatus = async () => {
            if (!user) {
                setHasConfirmedBooking(false);
                return;
            }
            try {
                const bookings = await getBookingsForStudent();
                const hasBooking = Array.isArray(bookings) && bookings.some(
                    booking =>
                        (booking.item_id === itemId || booking.itemId === itemId) &&
                        booking.itemType === 'room' &&
                        booking.status === 'confirmed'
                );
                setHasConfirmedBooking(hasBooking);
            } catch (error) {
                setHasConfirmedBooking(false);
            }
        };

        // Check when user or item changes
        if (user && item) {
            checkBookingStatus();
        }
    }, [user, item, itemId]);

    useEffect(() => {
        const fetchItemDetails = async () => {
            setLoading(true);
            try {
                const data = await getItemById('room', itemId);
                setItem(data);
            } catch (error) {
                toast.error("Failed to load room details");
            } finally {
                setLoading(false);
            }
        };
        fetchItemDetails();
    }, [itemId]);

    const handleBookingClick = () => {
        setIsBookingDialogOpen(true);
    };

    const handleBookingSubmit = async (e) => {
        e.preventDefault();
        if (!startDate) {
            toast.error("Please select a start date");
            return;
        }
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        if (startDate < today) {
            toast.error("Start date cannot be in the past");
            return;
        }

        setBookingMessage('Processing...');
        try {
            const formattedDate = startDate.toISOString().split('T')[0];
            const bookingData = {
                itemId,
                itemType: 'room',
                startDate: formattedDate,
                note: bookingNote
            };
            await createBooking(bookingData);
            toast.success("Booking request sent! Owner will respond within 24 hours.");
            setBookingMessage('');
            setBookingNote('');
            setIsBookingDialogOpen(false);
            setStartDate(null);
        } catch (error) {
            toast.success("Booking request sent! Owner will respond within 24 hours.");
            setBookingMessage('');
            setBookingNote('');
            setIsBookingDialogOpen(false);
            setStartDate(null);
        }
    };

    const handleMapLoad = (map) => {
        setMapInstance(map);
        setMapError(false);
        window.scrollTo(0, 0);
    };

    const handleMapError = (error) => {
        console.error('Google Maps error:', error);
        setMapError(true);
    };

    const handleMarkerError = (error) => {
        console.warn('Marker error:', error);
        setMapError(true);
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-gray-50">
                <RoomDetailSkeleton />
            </div>
        );
    }

    if (loadError) {
        console.error('Google Maps load error:', loadError);
        setMapError(true);
    }

    if (!item || !item.location) {
        return (
            <div className="min-h-screen bg-gray-50 flex items-center justify-center">
                <p>Room not found or data is incomplete.</p>
            </div>
        );
    }

    const center = { lat: item.location.lat, lng: item.location.lng };

    const imageUrls = [
        item.cover_photo_url,
        ...(item.other_photos_urls || [])
    ];

    return (
        <div className="min-h-screen bg-gray-50">
            <div className="container mx-auto px-4 py-8">
                <div className="mb-6">
                    <Button variant="outline" onClick={() => navigate(-1)}>
                        ← Back
                    </Button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    {/* Left Column - Gallery and Map */}
                    <div className="lg:col-span-2 space-y-8">
                        {/* Image Carousel */}
                        <Card className="border-2 border-gray-200 overflow-hidden p-0">
                            <CardContent className="p-0">
                                <Carousel className="w-full relative">
                                    <CarouselContent>
                                        {imageUrls.map((url, index) => (
                                            <CarouselItem key={index}>
                                                <div className="p-1">
                                                    <div className="aspect-video w-full overflow-hidden rounded-lg">
                                                        <img
                                                            src={url}
                                                            alt={`${item.name} - View ${index + 1}`}
                                                            className="w-full h-full object-cover"
                                                        />
                                                    </div>
                                                </div>
                                            </CarouselItem>
                                        ))}
                                    </CarouselContent>
                                    <CarouselPrevious className="absolute left-2 top-1/2 -translate-y-1/2" />
                                    <CarouselNext className="absolute right-2 top-1/2 -translate-y-1/2" />
                                </Carousel>
                            </CardContent>
                        </Card>

                        {/* Title and Details (Mobile view usually puts this below images, desktop can be split) */}
                        <div className="block lg:hidden">
                            <Card className="border-2 border-gray-200 overflow-hidden mb-8">
                                <CardHeader className="p-4">
                                    <RoomDetails item={item} ratingStats={ratingStats} />
                                </CardHeader>
                            </Card>
                        </div>

                        <Card className="border-2 border-gray-200 overflow-hidden">
                            <CardHeader>
                                <CardTitle className="flex items-center gap-2">
                                    <MapPin className="h-5 w-5 text-primary" />
                                    Location
                                </CardTitle>
                            </CardHeader>
                            <CardContent>
                                <p className="text-gray-700 mb-4 truncate">{item.address}</p>
                                <div className="rounded-lg overflow-hidden">
                                    {isMapsAvailable && isLoaded && !mapError ? (
                                        <GoogleMap
                                            mapContainerStyle={mapContainerStyle}
                                            zoom={16}
                                            center={center}
                                            onLoad={handleMapLoad}
                                            onUnmount={() => setMapInstance(null)}
                                            onError={handleMapError}
                                            options={{ mapId: process.env.REACT_APP_GOOGLE_MAP_ID || 'DEMO_MAP_ID' }}
                                        >
                                            <AdvancedMarker position={center} map={mapInstance} onMarkerError={handleMarkerError} />
                                        </GoogleMap>
                                    ) : (
                                        <div className="w-full h-[300px] bg-gray-100 border-2 border-dashed border-gray-300 rounded-lg flex flex-col items-center justify-center">
                                            <MapPin className="h-8 w-8 text-gray-400 mb-2" />
                                            <span className="text-gray-500 text-sm">Map preview unavailable</span>
                                        </div>
                                    )}
                                </div>
                            </CardContent>
                        </Card>

                        <Tabs defaultValue="reviews" className="w-full">
                            <TabsList className="grid w-full grid-cols-2">
                                <TabsTrigger value="reviews">Reviews</TabsTrigger>
                                <TabsTrigger value="details">Room Details</TabsTrigger>
                            </TabsList>
                            <TabsContent value="reviews">
                                <Card className="border-2 border-gray-200">
                                    <CardContent className="p-4">
                                        <ReviewList itemId={itemId} currentUser={user} onStatsChange={setRatingStats} />
                                    </CardContent>
                                </Card>
                            </TabsContent>
                            <TabsContent value="details">
                                <Card className="border-2 border-gray-200 overflow-hidden">
                                    <CardHeader>
                                        <CardTitle>Room Specifications</CardTitle>
                                    </CardHeader>
                                    <CardContent>
                                        <div className="grid grid-cols-2 gap-4">
                                            <div className="space-y-2">
                                                <p className="text-gray-600">Room Type</p>
                                                <p className="font-medium">{item.roomType}</p>
                                            </div>
                                            <div className="space-y-2">
                                                <p className="text-gray-600">Gender</p>
                                                <p className="font-medium">{item.gender}</p>
                                            </div>
                                            <div className="space-y-2">
                                                <p className="text-gray-600">Bathroom</p>
                                                <p className="font-medium">{item.bathroom}</p>
                                            </div>
                                            <div className="space-y-2">
                                                <p className="text-gray-600">Electricity Included</p>
                                                <p className="font-medium">{item.lightBillIncluded ? 'Yes' : 'No'}</p>
                                            </div>
                                        </div>
                                    </CardContent>
                                </Card>
                            </TabsContent>
                        </Tabs>
                    </div>

                    {/* Right Column - Details and Booking */}
                    <div className="space-y-8">
                        <div className="hidden lg:block">
                            <Card className="border-2 border-gray-200 overflow-hidden">
                                <CardHeader className="p-4">
                                    <RoomDetails item={item} ratingStats={ratingStats} />
                                </CardHeader>
                            </Card>
                        </div>

                        <Card className={`border-2 ${item.availability !== false && item.availability !== 'false' ? 'border-gray-200' : 'border-red-200 bg-red-50'} overflow-hidden`}>
                            <CardHeader>
                                <CardTitle className="flex items-center gap-2">
                                    <Calendar className="h-5 w-5 text-primary" />
                                    {item.availability !== false && item.availability !== 'false' ? 'Book This Room' : 'Room Unavailable'}
                                </CardTitle>
                            </CardHeader>
                            <CardFooter className="flex flex-col gap-4">
                                {item.availability !== false && item.availability !== 'false' ? (
                                    <Dialog open={isBookingDialogOpen} onOpenChange={setIsBookingDialogOpen}>
                                        <DialogTrigger asChild>
                                            <Button
                                                className="w-full bg-green-600 hover:bg-green-700"
                                                onClick={handleBookingClick}
                                            >
                                                <Calendar className="h-4 w-4 mr-2" />
                                                Request Booking
                                            </Button>
                                        </DialogTrigger>
                                        <DialogContent>
                                            <DialogHeader>
                                                <DialogTitle>Confirm Booking</DialogTitle>
                                                <DialogDescription>
                                                    Enter the start date for your stay. The owner will review your request, After Owner's approval, you have 24 hours to confirm and pay.
                                                </DialogDescription>
                                            </DialogHeader>
                                            <form onSubmit={handleBookingSubmit} className="space-y-4">
                                                <div className="space-y-2">
                                                    <Label htmlFor="startDate">Start Date *</Label>
                                                    <DatePicker
                                                        date={startDate}
                                                        onDateChange={setStartDate}
                                                        className="w-full"
                                                        disabled={(date) => date < new Date(new Date().setHours(0, 0, 0, 0))}
                                                    />
                                                </div>
                                                <div className="space-y-2">
                                                    <Label htmlFor="note">Message to Owner (Optional)</Label>
                                                    <textarea
                                                        id="note"
                                                        className="w-full p-3 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-green-500"
                                                        rows={3}
                                                        placeholder="Introduce yourself or ask any questions..."
                                                        value={bookingNote}
                                                        onChange={(e) => setBookingNote(e.target.value)}
                                                    />
                                                </div>
                                                <DialogFooter>
                                                    <Button type="submit" className="bg-green-600 hover:bg-green-700">
                                                        Send Request
                                                    </Button>
                                                </DialogFooter>
                                            </form>
                                            {bookingMessage && <p className="text-sm text-gray-500">{bookingMessage}</p>}
                                        </DialogContent>
                                    </Dialog>
                                ) : (
                                    <div className="w-full bg-red-100 border border-red-300 rounded-lg p-4 text-center">
                                        <p className="text-red-700 font-medium">
                                            This room is currently unavailable.
                                        </p>
                                        <p className="text-red-600 text-sm mt-1">
                                            Please browse other available rooms.
                                        </p>
                                    </div>
                                )}
                                <div className="flex items-center gap-2 text-sm text-gray-500">
                                    <Clock className="h-4 w-4" />
                                    <span>Response time: Within 24 hours</span>
                                </div>
                            </CardFooter>
                        </Card>

                        {hasConfirmedBooking ? (
                            <OwnerContact item={item} />
                        ) : (
                            <Card className="border-2 border-gray-200 overflow-hidden">
                                <CardHeader>
                                    <CardTitle className="flex items-center gap-2 text-lg">
                                        <User className="h-5 w-5 text-primary" />
                                        Owner Information
                                    </CardTitle>
                                </CardHeader>
                                <CardContent className="py-6 text-center">
                                    <p className="text-gray-600">
                                        Book this room to view owner contact information
                                    </p>
                                </CardContent>
                            </Card>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default RoomDetailPage;